PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE licenses (     id INTEGER PRIMARY KEY AUTOINCREMENT,      license_hash TEXT NOT NULL UNIQUE,      customer_name TEXT NOT NULL,     customer_email TEXT,      edition TEXT NOT NULL DEFAULT 'standard',     channel TEXT NOT NULL DEFAULT 'release',      status TEXT NOT NULL DEFAULT 'active'         CHECK (status IN ('active', 'suspended')),      expires_at TEXT,     is_lifetime INTEGER NOT NULL DEFAULT 0         CHECK (is_lifetime IN (0, 1)),      memo TEXT,      created_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      updated_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) , normalized_email TEXT);
CREATE TABLE devices (     id INTEGER PRIMARY KEY AUTOINCREMENT,      license_id INTEGER NOT NULL UNIQUE,      device_hash TEXT NOT NULL,      registered_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      last_auth_at TEXT,      last_client_time_utc TEXT,      last_clock_difference_seconds INTEGER,      last_app_version TEXT,      last_os_version TEXT,      FOREIGN KEY (license_id)         REFERENCES licenses(id)         ON DELETE CASCADE );
CREATE TABLE auth_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,      license_id INTEGER,      device_hash TEXT,      auth_result TEXT NOT NULL,      error_code TEXT,      client_time_utc TEXT,      server_time_utc TEXT,      clock_difference_seconds INTEGER,      app_version TEXT,      ip_address TEXT,      user_agent TEXT,      created_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), request_id TEXT, os_version TEXT,      FOREIGN KEY (license_id)         REFERENCES licenses(id)         ON DELETE SET NULL );
CREATE TABLE settings (     setting_key TEXT PRIMARY KEY,      setting_value TEXT NOT NULL,      description TEXT,      updated_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
CREATE TABLE admin_audit_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,      request_id TEXT,      license_id INTEGER,      action TEXT NOT NULL,      before_value TEXT,      after_value TEXT,      note TEXT,      ip_address TEXT,      user_agent TEXT,      created_at TEXT NOT NULL         DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      FOREIGN KEY (license_id)         REFERENCES licenses(id)         ON DELETE SET NULL );
CREATE TABLE stripe_events (   event_id TEXT PRIMARY KEY,   event_type TEXT NOT NULL,   processing_status TEXT NOT NULL     CHECK (processing_status IN ('processing', 'completed', 'failed')),   error_message TEXT,   received_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),   processed_at TEXT );
CREATE TABLE stripe_orders (   id INTEGER PRIMARY KEY AUTOINCREMENT,   stripe_event_id TEXT NOT NULL UNIQUE,   checkout_session_id TEXT NOT NULL UNIQUE,   payment_intent_id TEXT,   price_id TEXT NOT NULL,   customer_email TEXT NOT NULL,   normalized_email TEXT NOT NULL,   license_days INTEGER NOT NULL     CHECK (license_days IN (30, 90)),   amount_total INTEGER,   currency TEXT,   license_id INTEGER,   fulfillment_action TEXT     CHECK (fulfillment_action IN ('issued', 'extended')),   processing_status TEXT NOT NULL     CHECK (processing_status IN ('processing', 'completed', 'failed')),   error_message TEXT,   created_at TEXT NOT NULL     DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),   completed_at TEXT, license_key_ciphertext TEXT, license_key_iv TEXT, license_key_expires_at TEXT,   FOREIGN KEY (license_id) REFERENCES licenses(id) ON DELETE SET NULL );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_devices_device_hash ON devices(device_hash);
CREATE INDEX idx_auth_logs_license ON auth_logs(license_id);
CREATE INDEX idx_auth_logs_created ON auth_logs(created_at);
CREATE INDEX idx_auth_logs_request_id ON auth_logs(request_id);
CREATE INDEX idx_admin_audit_logs_license ON admin_audit_logs(license_id);
CREATE INDEX idx_admin_audit_logs_created ON admin_audit_logs(created_at);
CREATE INDEX idx_admin_audit_logs_request_id ON admin_audit_logs(request_id);
CREATE INDEX idx_stripe_orders_normalized_email ON stripe_orders(normalized_email);
CREATE UNIQUE INDEX idx_licenses_one_active_per_email ON licenses(normalized_email) WHERE status = 'active'   AND normalized_email IS NOT NULL;
